export type ComputeFunction<Prev, Next extends Prev = Prev> = (v: Prev) => PromiseLike<Next> | AsyncIterable<Next> | Next;
export type EffectFunction<Prev, Next extends Prev = Prev> = (v: Next, p?: Prev) => (() => void) | void;
export declare function createMemo<T>(compute: ComputeFunction<undefined | NoInfer<T>, T>): () => T;
export declare function createEffect<const T>(compute: (v: undefined | NoInfer<T>) => T, effectFn: EffectFunction<NoInfer<T>, T>): void;
export declare function createRenderEffect<const T>(compute: (v: undefined | NoInfer<T>) => T, effectFn: EffectFunction<NoInfer<T>, T>): void;
export declare function createSignal<T>(value: Exclude<T, Function>): [get: () => T, set: <U extends T>(value: Exclude<U, Function>) => U];
